import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { pathToFileURL } from 'node:url';

function validateRoot(root) {
  const stat = fs.lstatSync(root);
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw Error('root must be a non-symlink directory');
}
function isValidSelectedPath(selected) {
  return typeof selected === 'string'
    && selected.length > 0
    && !selected.startsWith('/')
    && !selected.includes('\\')
    && !selected.includes('\0')
    && selected.split('/').every(part => part !== '' && part !== '.' && part !== '..');
}
function validatePath(selected) {
  if (!isValidSelectedPath(selected)) throw Error('invalid selected path');
}
// Walk each component beneath root with lstat (never follows symlinks).
// Returns {kind:'missing'} when any component is absent, {kind:'unsafe'} at
// the first unsafe component, or {kind:'file', path, stat} for a regular file.
function walkSelected(root, selected) {
  const parts = selected.split('/');
  let current = root;
  for (let i = 0; i < parts.length; i++) {
    current = path.join(current, parts[i]);
    let stat;
    try { stat = fs.lstatSync(current); }
    catch (error) { if (error.code === 'ENOENT') return {kind:'missing'}; throw error; }
    if (stat.isSymbolicLink() || (i === parts.length - 1 ? !stat.isFile() : !stat.isDirectory())) return {kind:'unsafe'};
  }
  return {kind:'file', path:current, stat};
}
function inspect(root, selected) {
  const walked = walkSelected(root, selected);
  if (walked.kind !== 'file') return walked;
  const bytes = fs.readFileSync(walked.path);
  return {kind:'file',sha256:crypto.createHash('sha256').update(bytes).digest('hex'),size:bytes.length,mode:walked.stat.mode & 0o777};
}
export function createManifest(root, paths) {
  validateRoot(root);
  if (!Array.isArray(paths)) throw Error('paths must be an array');
  const seen = new Set();
  for (const selected of paths) {
    validatePath(selected);
    if (seen.has(selected)) throw Error('duplicate selection');
    seen.add(selected);
  }
  return {version:1,files:[...paths].sort().map(selected => {
    const current = inspect(root, selected);
    if (current.kind !== 'file') throw Error(`${current.kind} selected path`);
    return {path:selected,sha256:current.sha256,size:current.size,mode:current.mode};
  })};
}
const SHA256_RE = /^[0-9a-f]{64}$/;
function validateManifest(manifest) {
  if (typeof manifest !== 'object' || manifest === null || Array.isArray(manifest)) throw Error('manifest must be an object');
  if (manifest.version !== 1) throw Error('manifest version must be 1');
  if (!Array.isArray(manifest.files)) throw Error('manifest files must be an array');
  const seen = new Set();
  for (const entry of manifest.files) {
    if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) throw Error('manifest entry must be an object');
    if (!isValidSelectedPath(entry.path)) throw Error('invalid selected path');
    if (seen.has(entry.path)) throw Error('duplicate selection');
    seen.add(entry.path);
    if (typeof entry.sha256 !== 'string' || !SHA256_RE.test(entry.sha256)) throw Error('manifest sha256 must be 64 lowercase hexadecimal characters');
    if (!Number.isSafeInteger(entry.size) || entry.size < 0) throw Error('manifest size must be a nonnegative safe integer');
    if (!Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 511) throw Error('manifest mode must be an integer in 0..511');
  }
}
const compareSelected = (a, b) => a < b ? -1 : a > b ? 1 : 0;
export function verifyManifest(root, manifest) {
  validateRoot(root);
  validateManifest(manifest);
  const unchanged = [];
  const changed = [];
  const missing = [];
  const unsafe = [];
  for (const entry of manifest.files) {
    const walked = walkSelected(root, entry.path);
    if (walked.kind === 'missing') { missing.push(entry.path); continue; }
    if (walked.kind !== 'file') { unsafe.push(entry.path); continue; }
    const bytes = fs.readFileSync(walked.path);
    const reasons = [];
    if (crypto.createHash('sha256').update(bytes).digest('hex') !== entry.sha256 || bytes.length !== entry.size) reasons.push('content');
    if ((walked.stat.mode & 0o777) !== entry.mode) reasons.push('mode');
    if (reasons.length === 0) unchanged.push(entry.path);
    else changed.push({path:entry.path, reasons});
  }
  unchanged.sort(compareSelected);
  changed.sort((a, b) => compareSelected(a.path, b.path));
  missing.sort(compareSelected);
  unsafe.sort(compareSelected);
  return {
    ok:changed.length === 0 && missing.length === 0 && unsafe.length === 0,
    unchanged,
    changed,
    missing,
    unsafe,
  };
}
function printJson(value) {
  process.stdout.write(`${JSON.stringify(value)}\n`);
}
function runCli(argv) {
  try {
    const [command, ...rest] = argv;
    if (command === 'create') {
      if (rest.length === 0) throw Error('usage: node snapshot.js create ROOT [PATH ...]');
      const [root, ...selected] = rest;
      printJson(createManifest(root, selected));
      return 0;
    }
    if (command === 'verify') {
      if (rest.length !== 2) throw Error('usage: node snapshot.js verify ROOT MANIFEST_FILE');
      const [root, manifestFile] = rest;
      const manifest = JSON.parse(fs.readFileSync(manifestFile, 'utf8'));
      const report = verifyManifest(root, manifest);
      printJson(report);
      return report.ok ? 0 : 1;
    }
    throw Error('usage: node snapshot.js create ROOT [PATH ...] | node snapshot.js verify ROOT MANIFEST_FILE');
  } catch (error) {
    process.stderr.write(`snapshot: ${error instanceof Error && error.message ? error.message : String(error)}\n`);
    return 2;
  }
}
function isCliEntry() {
  const entryPath = process.argv[1];
  if (typeof entryPath !== 'string' || entryPath.length === 0) return false;
  try {
    if (pathToFileURL(entryPath).href === import.meta.url) return true;
    return pathToFileURL(fs.realpathSync(entryPath)).href === import.meta.url;
  } catch {
    return false;
  }
}
if (isCliEntry()) process.exitCode = runCli(process.argv.slice(2));

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import * as snapshot from '../snapshot.js';

const cliEntry = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function sha256(data) { return crypto.createHash('sha256').update(data).digest('hex'); }
function fixture(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-verify-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}
function runCli(args) {
  return spawnSync(process.execPath, [cliEntry, ...args], { encoding: 'utf8' });
}
function entryFor(root, selected, overrides = {}) {
  const stat = fs.statSync(path.join(root, selected));
  const bytes = fs.readFileSync(path.join(root, selected));
  return { path: selected, sha256: sha256(bytes), size: bytes.length, mode: stat.mode & 0o777, ...overrides };
}

test('verifyManifest rejects invalid manifests', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  const good = entryFor(root, 'a.txt');
  const bad = [
    null,
    undefined,
    5,
    'manifest',
    true,
    [],
    { version: 0, files: [] },
    { version: '1', files: [] },
    { version: true, files: [] },
    { files: [] },
    { version: 1 },
    { version: 1, files: {} },
    { version: 1, files: null },
    { version: 1, files: [null] },
    { version: 1, files: [42] },
    { version: 1, files: [[]] },
    { version: 1, files: [{}] },
    { version: 1, files: [{ ...good, path: '/absolute' }] },
    { version: 1, files: [{ ...good, path: 'a\\b' }] },
    { version: 1, files: [{ ...good, path: 'a\0b' }] },
    { version: 1, files: [{ ...good, path: 'a/./b' }] },
    { version: 1, files: [{ ...good, path: 'a/../b' }] },
    { version: 1, files: [{ ...good, path: 'a//b' }] },
    { version: 1, files: [{ ...good, path: 'a/' }] },
    { version: 1, files: [{ ...good, path: '' }] },
    { version: 1, files: [{ ...good, path: 7 }] },
    { version: 1, files: [{ ...good, path: null }] },
    { version: 1, files: [{ ...good, sha256: good.sha256.toUpperCase() }] },
    { version: 1, files: [{ ...good, sha256: good.sha256.slice(0, 63) }] },
    { version: 1, files: [{ ...good, sha256: good.sha256 + '0' }] },
    { version: 1, files: [{ ...good, sha256: 'g'.repeat(64) }] },
    { version: 1, files: [{ ...good, sha256: 1 }] },
    { version: 1, files: [{ ...good, size: -1 }] },
    { version: 1, files: [{ ...good, size: 1.5 }] },
    { version: 1, files: [{ ...good, size: Number.MAX_SAFE_INTEGER + 1 }] },
    { version: 1, files: [{ ...good, size: '3' }] },
    { version: 1, files: [{ ...good, size: null }] },
    { version: 1, files: [{ ...good, mode: -1 }] },
    { version: 1, files: [{ ...good, mode: 512 }] },
    { version: 1, files: [{ ...good, mode: 0.5 }] },
    { version: 1, files: [{ ...good, mode: '644' }] },
    { version: 1, files: [{ ...good, mode: null }] },
    { version: 1, files: [{ ...good }, { ...good }] },
  ];
  for (const manifest of bad) {
    assert.throws(() => snapshot.verifyManifest(root, manifest), Error, `expected throw for ${JSON.stringify(manifest) ?? typeof manifest}`);
  }
  // Unknown object fields are ignored at both levels.
  assert.deepEqual(
    snapshot.verifyManifest(root, { version: 1, note: 'extra', files: [{ ...good, extra: 1 }] }),
    { ok: true, unchanged: ['a.txt'], changed: [], missing: [], unsafe: [] },
  );
});

test('verifyManifest rejects invalid roots', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  const manifest = { version: 1, files: [entryFor(root, 'a.txt')] };
  assert.throws(() => snapshot.verifyManifest(path.join(root, 'nope'), manifest));
  assert.throws(() => snapshot.verifyManifest(path.join(root, 'a.txt'), manifest));
  fs.symlinkSync(root, path.join(root, 'rootlink'));
  assert.throws(() => snapshot.verifyManifest(path.join(root, 'rootlink'), manifest));
});

test('verifyManifest classifies content, mode, missing and unsafe', t => {
  const root = fixture(t);
  const dir = path.join(root, 'd');
  fs.mkdirSync(dir);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc'); fs.chmodSync(path.join(root, 'a.txt'), 0o644);
  fs.writeFileSync(path.join(dir, 'b.txt'), 'def'); fs.chmodSync(path.join(dir, 'b.txt'), 0o600);
  fs.writeFileSync(path.join(root, 'c.txt'), 'ghi'); fs.chmodSync(path.join(root, 'c.txt'), 0o640);
  fs.writeFileSync(path.join(root, 's.txt'), 'same'); fs.chmodSync(path.join(root, 's.txt'), 0o444);
  fs.writeFileSync(path.join(root, 'f.txt'), 'file'); // regular file used as a bad intermediate
  fs.symlinkSync(path.join(root, 'a.txt'), path.join(root, 'slink')); // final symlink (inside root)
  fs.symlinkSync(dir, path.join(root, 'dlink')); // intermediate symlink
  const manifest = { version: 1, files: [
    entryFor(root, 'c.txt'),
    entryFor(root, 'a.txt'),
    entryFor(root, 'd/b.txt'),
    entryFor(root, 's.txt'),
    { path: 'gone.txt', sha256: sha256('x'), size: 1, mode: 0o644 },
    { path: 'd/gone.txt', sha256: sha256('x'), size: 1, mode: 0o644 },
    { path: 'nodir/x.txt', sha256: sha256('x'), size: 1, mode: 0o644 },
    { path: 'slink', sha256: sha256('x'), size: 1, mode: 0o644 },
    { path: 'dlink/x.txt', sha256: sha256('x'), size: 1, mode: 0o644 },
    { path: 'd', sha256: sha256('x'), size: 1, mode: 0o755 },
    { path: 'f.txt/x', sha256: sha256('x'), size: 1, mode: 0o644 },
  ]};
  // Drift: a.txt content only, c.txt mode only, d/b.txt both.
  fs.writeFileSync(path.join(root, 'a.txt'), 'xyz');
  fs.chmodSync(path.join(root, 'c.txt'), 0o644);
  fs.writeFileSync(path.join(dir, 'b.txt'), 'DEF');
  fs.chmodSync(path.join(dir, 'b.txt'), 0o601);
  assert.deepEqual(snapshot.verifyManifest(root, manifest), {
    ok: false,
    unchanged: ['s.txt'],
    changed: [
      { path: 'a.txt', reasons: ['content'] },
      { path: 'c.txt', reasons: ['mode'] },
      { path: 'd/b.txt', reasons: ['content', 'mode'] },
    ],
    missing: ['d/gone.txt', 'gone.txt', 'nodir/x.txt'],
    unsafe: ['d', 'dlink/x.txt', 'f.txt/x', 'slink'],
  });
});

test('same content with same size but different bytes is content drift', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  const manifest = snapshot.createManifest(root, ['a.txt']);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abd'); // same size, different bytes
  const report = snapshot.verifyManifest(root, manifest);
  assert.deepEqual(report.changed, [{ path: 'a.txt', reasons: ['content'] }]);
});

test('verifyManifest does not require sorted entries and sorts output', t => {
  const root = fixture(t);
  for (const [name, data] of [['z.txt', '1'], ['a.txt', '2'], ['m/n.txt', '3']]) {
    const file = path.join(root, name);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, data);
  }
  const manifest = { version: 1, files: [
    entryFor(root, 'z.txt'),
    entryFor(root, 'a.txt'),
    entryFor(root, 'm/n.txt'),
  ]};
  assert.deepEqual(snapshot.verifyManifest(root, manifest), {
    ok: true,
    unchanged: ['a.txt', 'm/n.txt', 'z.txt'],
    changed: [],
    missing: [],
    unsafe: [],
  });
});

test('APIs do not mutate their inputs', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'b.txt'), '1');
  fs.writeFileSync(path.join(root, 'a.txt'), '2');
  const paths = ['b.txt', 'a.txt'];
  const pathsBefore = [...paths];
  const manifest = snapshot.createManifest(root, paths);
  assert.deepEqual(paths, pathsBefore);
  assert.deepEqual(manifest.files.map(file => file.path), ['a.txt', 'b.txt']);
  const before = JSON.parse(JSON.stringify(manifest));
  const report = snapshot.verifyManifest(root, manifest);
  assert.deepEqual(manifest, before);
  assert.ok(report.ok);
  // The returned report objects are fresh and sorted, independent of manifest order.
  assert.deepEqual(report.unchanged, ['a.txt', 'b.txt']);
});

test('exotic filename characters are supported', t => {
  const root = fixture(t);
  const name = 'we ird\tfile\nünïcødé 名字';
  fs.writeFileSync(path.join(root, name), 'data');
  const manifest = snapshot.createManifest(root, [name]);
  assert.equal(manifest.files[0].size, 4);
  assert.equal(manifest.files[0].sha256, sha256('data'));
  assert.deepEqual(snapshot.verifyManifest(root, manifest).unchanged, [name]);
});

test('createManifest still rejects missing, unsafe and duplicate selections', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.symlinkSync(path.join(root, 'a.txt'), path.join(root, 'slink'));
  assert.throws(() => snapshot.createManifest(root, ['gone.txt']));
  assert.throws(() => snapshot.createManifest(root, ['slink']));
  assert.throws(() => snapshot.createManifest(root, ['a.txt', 'a.txt']));
  assert.throws(() => snapshot.createManifest(root, ['a.txt/b']));
  assert.throws(() => snapshot.createManifest(root, [])); // root ok, empty ok... wait
});

test('createManifest allows empty selection', t => {
  const root = fixture(t);
  assert.deepEqual(snapshot.createManifest(root, []), { version: 1, files: [] });
});

test('cli create prints manifest and exits 0', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.chmodSync(path.join(root, 'a.txt'), 0o640);
  let res = runCli(['create', root, 'a.txt']);
  assert.equal(res.status, 0);
  assert.equal(res.stderr, '');
  assert.ok(res.stdout.endsWith('\n'));
  assert.deepEqual(JSON.parse(res.stdout), {
    version: 1,
    files: [{ path: 'a.txt', sha256: sha256('abc'), size: 3, mode: 0o640 }],
  });
  res = runCli(['create', root]);
  assert.equal(res.status, 0);
  assert.deepEqual(JSON.parse(res.stdout), { version: 1, files: [] });
});

test('cli verify exits 0 for ok and 1 for drift', t => {
  const root = fixture(t);
  const manifestFile = path.join(root, 'm.json');
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.writeFileSync(manifestFile, JSON.stringify(snapshot.createManifest(root, ['a.txt'])));
  let res = runCli(['verify', root, manifestFile]);
  assert.equal(res.status, 0);
  assert.equal(res.stderr, '');
  assert.deepEqual(JSON.parse(res.stdout), { ok: true, unchanged: ['a.txt'], changed: [], missing: [], unsafe: [] });
  fs.writeFileSync(path.join(root, 'a.txt'), 'nope');
  res = runCli(['verify', root, manifestFile]);
  assert.equal(res.status, 1);
  assert.equal(res.stderr, '');
  const report = JSON.parse(res.stdout);
  assert.equal(report.ok, false);
  assert.deepEqual(report.changed, [{ path: 'a.txt', reasons: ['content'] }]);
});

test('cli errors exit 2 with nonempty stderr and no stdout', t => {
  const root = fixture(t);
  const manifestFile = path.join(root, 'm.json');
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.writeFileSync(manifestFile, JSON.stringify(snapshot.createManifest(root, ['a.txt'])));
  const badCases = [
    [],
    ['bogus'],
    ['create'],
    ['create', path.join(root, 'nope'), 'a.txt'],
    ['create', root, '/absolute'],
    ['create', root, '../up'],
    ['verify', root],
    ['verify', root, manifestFile, 'extra'],
    ['verify', root, path.join(root, 'missing-file.json')],
    ['verify', path.join(root, 'a.txt'), manifestFile],
  ];
  for (const args of badCases) {
    const res = runCli(args);
    assert.equal(res.status, 2, `args=${JSON.stringify(args)} stderr=${res.stderr}`);
    assert.notEqual(res.stderr, '');
    assert.equal(res.stdout, '');
  }
  fs.writeFileSync(manifestFile, '{not json');
  let res = runCli(['verify', root, manifestFile]);
  assert.equal(res.status, 2);
  assert.equal(res.stdout, '');
  assert.notEqual(res.stderr, '');
  fs.writeFileSync(manifestFile, JSON.stringify({ version: 1, files: [{ path: 'a.txt', sha256: 'f'.repeat(64), size: 3, mode: 999 }] }));
  res = runCli(['verify', root, manifestFile]);
  assert.equal(res.status, 2);
  assert.equal(res.stdout, '');
  assert.notEqual(res.stderr, '');
  fs.writeFileSync(manifestFile, JSON.stringify(snapshot.createManifest(root, ['a.txt'])));
  fs.rmSync(path.join(root, 'a.txt'));
  res = runCli(['verify', root, manifestFile]);
  assert.equal(res.status, 1); // valid manifest, drift (missing) is not an error
  assert.equal(JSON.parse(res.stdout).ok, false);
});

test('importing the module does not run the CLI', () => {
  const res = spawnSync(process.execPath, ['-e', `import(${JSON.stringify(pathToFileURL(cliEntry).href)});`], { encoding: 'utf8' });
  assert.equal(res.status, 0);
  assert.equal(res.stdout, '');
  assert.equal(res.stderr, '');
});

