import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { pathToFileURL } from 'node:url';

function validateRoot(root) {
  const stat = fs.lstatSync(root);
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw Error('root must be a non-symlink directory');
}
function isValidSelectedPath(selected) {
  return typeof selected === 'string'
    && selected.length > 0
    && !selected.startsWith('/')
    && !selected.includes('\\')
    && !selected.includes('\0')
    && selected.split('/').every(part => part !== '' && part !== '.' && part !== '..');
}
function validatePath(selected) {
  if (!isValidSelectedPath(selected)) throw Error('invalid selected path');
}
// Walk each component beneath root with lstat (never follows symlinks).
// Returns {kind:'missing'} when any component is absent, {kind:'unsafe'} at
// the first unsafe component, or {kind:'file', path, stat} for a regular file.
function walkSelected(root, selected) {
  const parts = selected.split('/');
  let current = root;
  let stat;
  for (let i = 0; i < parts.length; i++) {
    current = path.join(current, parts[i]);
    try { stat = fs.lstatSync(current); }
    catch (error) { if (error.code === 'ENOENT') return {kind:'missing'}; throw error; }
    if (stat.isSymbolicLink() || (i === parts.length - 1 ? !stat.isFile() : !stat.isDirectory())) return {kind:'unsafe'};
