  const walked = walkSelected(root, selected);
  if (walked.kind !== 'file') return walked;
  const bytes = fs.readFileSync(walked.path);
  return {kind:'file',sha256:crypto.createHash('sha256').update(bytes).digest('hex'),size:bytes.length,mode:walked.stat.mode & 0o777};
}
export function createManifest(root, paths) {
  validateRoot(root);
  if (!Array.isArray(paths)) throw Error('paths must be an array');
  const seen = new Set();
  for (const selected of paths) {
    validatePath(selected);
    if (seen.has(selected)) throw Error('duplicate selection');
    seen.add(selected);
  }
  return {version:1,files:[...paths].sort().map(selected => {
    const current = inspect(root, selected);
    if (current.kind !== 'file') throw Error(`${current.kind} selected path`);
    return {path:selected,sha256:current.sha256,size:current.size,mode:current.mode};
  })};
}
const SHA256_RE = /^[0-9a-f]{64}$/;
function validateManifest(manifest) {
  if (typeof manifest !== 'object' || manifest === null || Array.isArray(manifest)) throw Error('manifest must be an object');
  if (manifest.version !== 1) throw Error('manifest version must be 1');
  if (!Array.isArray(manifest.files)) throw Error('manifest files must be an array');
