import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import * as snapshot from '../snapshot.js';

const cliEntry = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function sha256(data) { return crypto.createHash('sha256').update(data).digest('hex'); }
function fixture(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-verify-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}
function runCli(args) {
  return spawnSync(process.execPath, [cliEntry, ...args], { encoding: 'utf8' });
}
function entryFor(root, selected, overrides = {}) {
  const stat = fs.statSync(path.join(root, selected));
  const bytes = fs.readFileSync(path.join(root, selected));
  return { path: selected, sha256: sha256(bytes), size: bytes.length, mode: stat.mode & 0o777, ...overrides };
}

test('verifyManifest rejects invalid manifests', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  const good = entryFor(root, 'a.txt');
  const bad = [
    null,
    undefined,
    5,
    'manifest',
    true,
    [],
    { version: 0, files: [] },
    { version: '1', files: [] },
    { version: true, files: [] },
    { files: [] },
    { version: 1 },
    { version: 1, files: {} },
    { version: 1, files: null },
    { version: 1, files: [null] },
    { version: 1, files: [42] },
    { version: 1, files: [[]] },
    { version: 1, files: [{}] },
    { version: 1, files: [{ ...good, path: '/absolute' }] },
    { version: 1, files: [{ ...good, path: 'a\\b' }] },
    { version: 1, files: [{ ...good, path: 'a\0b' }] },
    { version: 1, files: [{ ...good, path: 'a/./b' }] },
    { version: 1, files: [{ ...good, path: 'a/../b' }] },
    { version: 1, files: [{ ...good, path: 'a//b' }] },
    { version: 1, files: [{ ...good, path: 'a/' }] },
    { version: 1, files: [{ ...good, path: '' }] },
    { version: 1, files: [{ ...good, path: 7 }] },
    { version: 1, files: [{ ...good, path: null }] },
    { version: 1, files: [{ ...good, sha256: good.sha256.toUpperCase() }] },
    { version: 1, files: [{ ...good, sha256: good.sha256.slice(0, 63) }] },
    { version: 1, files: [{ ...good, sha256: good.sha256 + '0' }] },
    { version: 1, files: [{ ...good, sha256: 'g'.repeat(64) }] },
    { version: 1, files: [{ ...good, sha256: 1 }] },
    { version: 1, files: [{ ...good, size: -1 }] },
    { version: 1, files: [{ ...good, size: 1.5 }] },
    { version: 1, files: [{ ...good, size: Number.MAX_SAFE_INTEGER + 1 }] },
    { version: 1, files: [{ ...good, size: '3' }] },
    { version: 1, files: [{ ...good, size: null }] },
    { version: 1, files: [{ ...good, mode: -1 }] },
    { version: 1, files: [{ ...good, mode: 512 }] },
    { version: 1, files: [{ ...good, mode: 0.5 }] },
    { version: 1, files: [{ ...good, mode: '644' }] },
    { version: 1, files: [{ ...good, mode: null }] },
    { version: 1, files: [{ ...good }, { ...good }] },
  ];
  for (const manifest of bad) {
    assert.throws(() => snapshot.verifyManifest(root, manifest), Error, `expected throw for ${JSON.stringify(manifest) ?? typeof manifest}`);
  }
  // Unknown object fields are ignored at both levels.
  assert.deepEqual(
    snapshot.verifyManifest(root, { version: 1, note: 'extra', files: [{ ...good, extra: 1 }] }),
    { ok: true, unchanged: ['a.txt'], changed: [], missing: [], unsafe: [] },
  );
});

test('verifyManifest rejects invalid roots', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  const manifest = { version: 1, files: [entryFor(root, 'a.txt')] };
  assert.throws(() => snapshot.verifyManifest(path.join(root, 'nope'), manifest));
  assert.throws(() => snapshot.verifyManifest(path.join(root, 'a.txt'), manifest));
  fs.symlinkSync(root, path.join(root, 'rootlink'));
  assert.throws(() => snapshot.verifyManifest(path.join(root, 'rootlink'), manifest));
});

test('verifyManifest classifies content, mode, missing and unsafe', t => {
  const root = fixture(t);
  const dir = path.join(root, 'd');
  fs.mkdirSync(dir);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc'); fs.chmodSync(path.join(root, 'a.txt'), 0o644);
  fs.writeFileSync(path.join(dir, 'b.txt'), 'def'); fs.chmodSync(path.join(dir, 'b.txt'), 0o600);
  fs.writeFileSync(path.join(root, 'c.txt'), 'ghi'); fs.chmodSync(path.join(root, 'c.txt'), 0o640);
  fs.writeFileSync(path.join(root, 's.txt'), 'same'); fs.chmodSync(path.join(root, 's.txt'), 0o444);
  fs.writeFileSync(path.join(root, 'f.txt'), 'file'); // regular file used as a bad intermediate
  fs.symlinkSync(path.join(root, 'a.txt'), path.join(root, 'slink')); // final symlink (inside root)
  fs.symlinkSync(dir, path.join(root, 'dlink')); // intermediate symlink
  const manifest = { version: 1, files: [
    entryFor(root, 'c.txt'),
    entryFor(root, 'a.txt'),
    entryFor(root, 'd/b.txt'),
    entryFor(root, 's.txt'),
    { path: 'gone.txt', sha256: sha256('x'), size: 1, mode: 0o644 },
    { path: 'd/gone.txt', sha256: sha256('x'), size: 1, mode: 0o644 },
    { path: 'nodir/x.txt', sha256: sha256('x'), size: 1, mode: 0o644 },
    { path: 'slink', sha256: sha256('x'), size: 1, mode: 0o644 },
    { path: 'dlink/x.txt', sha256: sha256('x'), size: 1, mode: 0o644 },
    { path: 'd', sha256: sha256('x'), size: 1, mode: 0o755 },
    { path: 'f.txt/x', sha256: sha256('x'), size: 1, mode: 0o644 },
  ]};
  // Drift: a.txt content only, c.txt mode only, d/b.txt both.
  fs.writeFileSync(path.join(root, 'a.txt'), 'xyz');
  fs.chmodSync(path.join(root, 'c.txt'), 0o644);
  fs.writeFileSync(path.join(dir, 'b.txt'), 'DEF');
  fs.chmodSync(path.join(dir, 'b.txt'), 0o601);
  assert.deepEqual(snapshot.verifyManifest(root, manifest), {
    ok: false,
    unchanged: ['s.txt'],
    changed: [
      { path: 'a.txt', reasons: ['content'] },
      { path: 'c.txt', reasons: ['mode'] },
      { path: 'd/b.txt', reasons: ['content', 'mode'] },
    ],
    missing: ['d/gone.txt', 'gone.txt', 'nodir/x.txt'],
    unsafe: ['d', 'dlink/x.txt', 'f.txt/x', 'slink'],
  });
