test('same content with same size but different bytes is content drift', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  const manifest = snapshot.createManifest(root, ['a.txt']);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abd'); // same size, different bytes
  const report = snapshot.verifyManifest(root, manifest);
  assert.deepEqual(report.changed, [{ path: 'a.txt', reasons: ['content'] }]);
});

test('verifyManifest does not require sorted entries and sorts output', t => {
  const root = fixture(t);
  for (const [name, data] of [['z.txt', '1'], ['a.txt', '2'], ['m/n.txt', '3']]) {
    const file = path.join(root, name);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, data);
  }
  const manifest = { version: 1, files: [
    entryFor(root, 'z.txt'),
    entryFor(root, 'a.txt'),
    entryFor(root, 'm/n.txt'),
  ]};
  assert.deepEqual(snapshot.verifyManifest(root, manifest), {
    ok: true,
    unchanged: ['a.txt', 'm/n.txt', 'z.txt'],
    changed: [],
    missing: [],
    unsafe: [],
  });
});

test('APIs do not mutate their inputs', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'b.txt'), '1');
  fs.writeFileSync(path.join(root, 'a.txt'), '2');
  const paths = ['b.txt', 'a.txt'];
  const pathsBefore = [...paths];
  const manifest = snapshot.createManifest(root, paths);
  assert.deepEqual(paths, pathsBefore);
  assert.deepEqual(manifest.files.map(file => file.path), ['a.txt', 'b.txt']);
  const before = JSON.parse(JSON.stringify(manifest));
  const report = snapshot.verifyManifest(root, manifest);
  assert.deepEqual(manifest, before);
  assert.ok(report.ok);
  // The returned report objects are fresh and sorted, independent of manifest order.
  assert.deepEqual(report.unchanged, ['a.txt', 'b.txt']);
});

test('exotic filename characters are supported', t => {
  const root = fixture(t);
  const name = 'we ird\tfile\nünïcødé 名字';
  fs.writeFileSync(path.join(root, name), 'data');
  const manifest = snapshot.createManifest(root, [name]);
  assert.equal(manifest.files[0].size, 4);
  assert.equal(manifest.files[0].sha256, sha256('data'));
  assert.deepEqual(snapshot.verifyManifest(root, manifest).unchanged, [name]);
});

test('createManifest still rejects missing, unsafe and duplicate selections', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.symlinkSync(path.join(root, 'a.txt'), path.join(root, 'slink'));
  assert.throws(() => snapshot.createManifest(root, ['gone.txt']));
  assert.throws(() => snapshot.createManifest(root, ['slink']));
  assert.throws(() => snapshot.createManifest(root, ['a.txt', 'a.txt']));
  assert.throws(() => snapshot.createManifest(root, ['a.txt/b']));
  assert.throws(() => snapshot.createManifest(root, 'a.txt'));
  assert.throws(() => snapshot.createManifest(root, ['a.txt', 5]));
});

test('createManifest allows empty selection', t => {
  const root = fixture(t);
  assert.deepEqual(snapshot.createManifest(root, []), { version: 1, files: [] });
});

test('cli create prints manifest and exits 0', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.chmodSync(path.join(root, 'a.txt'), 0o640);
  let res = runCli(['create', root, 'a.txt']);
  assert.equal(res.status, 0);
  assert.equal(res.stderr, '');
  assert.ok(res.stdout.endsWith('\n'));
  assert.deepEqual(JSON.parse(res.stdout), {
    version: 1,
    files: [{ path: 'a.txt', sha256: sha256('abc'), size: 3, mode: 0o640 }],
  });
  res = runCli(['create', root]);
  assert.equal(res.status, 0);
  assert.deepEqual(JSON.parse(res.stdout), { version: 1, files: [] });
});

test('cli verify exits 0 for ok and 1 for drift', t => {
  const root = fixture(t);
  const manifestFile = path.join(root, 'm.json');
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.writeFileSync(manifestFile, JSON.stringify(snapshot.createManifest(root, ['a.txt'])));
  let res = runCli(['verify', root, manifestFile]);
  assert.equal(res.status, 0);
  assert.equal(res.stderr, '');
  assert.deepEqual(JSON.parse(res.stdout), { ok: true, unchanged: ['a.txt'], changed: [], missing: [], unsafe: [] });
  fs.writeFileSync(path.join(root, 'a.txt'), 'nope');
  res = runCli(['verify', root, manifestFile]);
  assert.equal(res.status, 1);
  assert.equal(res.stderr, '');
  const report = JSON.parse(res.stdout);
  assert.equal(report.ok, false);
  assert.deepEqual(report.changed, [{ path: 'a.txt', reasons: ['content'] }]);
});

test('cli errors exit 2 with nonempty stderr and no stdout', t => {
  const root = fixture(t);
  const manifestFile = path.join(root, 'm.json');
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.writeFileSync(manifestFile, JSON.stringify(snapshot.createManifest(root, ['a.txt'])));
  const badCases = [
    [],
    ['bogus'],
    ['create'],
    ['create', path.join(root, 'nope'), 'a.txt'],
    ['create', root, '/absolute'],
    ['create', root, '../up'],
    ['verify', root],
    ['verify', root, manifestFile, 'extra'],
    ['verify', root, path.join(root, 'missing-file.json')],
    ['verify', path.join(root, 'a.txt'), manifestFile],
  ];
  for (const args of badCases) {
    const res = runCli(args);
    assert.equal(res.status, 2, `args=${JSON.stringify(args)} stderr=${res.stderr}`);
    assert.notEqual(res.stderr, '');
    assert.equal(res.stdout, '');
  }
  fs.writeFileSync(manifestFile, '{not json');
  let res = runCli(['verify', root, manifestFile]);
  assert.equal(res.status, 2);
  assert.equal(res.stdout, '');
  assert.notEqual(res.stderr, '');
  fs.writeFileSync(manifestFile, JSON.stringify({ version: 1, files: [{ path: 'a.txt', sha256: 'f'.repeat(64), size: 3, mode: 999 }] }));
  res = runCli(['verify', root, manifestFile]);
  assert.equal(res.status, 2);
  assert.equal(res.stdout, '');
  assert.notEqual(res.stderr, '');
  fs.writeFileSync(manifestFile, JSON.stringify(snapshot.createManifest(root, ['a.txt'])));
  fs.rmSync(path.join(root, 'a.txt'));
  res = runCli(['verify', root, manifestFile]);
  assert.equal(res.status, 1); // valid manifest, drift (missing) is not an error
  assert.equal(JSON.parse(res.stdout).ok, false);
});

test('importing the module does not run the CLI', () => {
  const res = spawnSync(process.execPath, ['-e', `import(${JSON.stringify(pathToFileURL(cliEntry).href)});`], { encoding: 'utf8' });
  assert.equal(res.status, 0);
  assert.equal(res.stdout, '');
  assert.equal(res.stderr, '');
});

